extends SceneTree

func _init():
	var controller = load("res://scripts/FieldController.gd").new()
	var test_cases = [
		{ "pos": Vector2(0, 0), "expected": Vector2(300, 400) },
		{ "pos": Vector2(900, -300), "expected": Vector2(-282.843, -282.843) },
		{ "pos": Vector2(-900, -300), "expected": Vector2(-250, 0) },
		{ "pos": Vector2(1700, 300), "expected": Vector2(0, 800) },
		{ "pos": Vector2(1400, 300), "expected": Vector2(300, 400) },
		{ "pos": Vector2(3000, 0), "expected": Vector2(0, 100) },
		{ "pos": Vector2(0, 2000), "expected": Vector2(0, 300) }
	]

	print("Running FieldController tests...")
	var all_passed = true
	for tc in test_cases:
		var result = controller.net_gravity_at(tc.pos)
		var diff = (result - tc.expected).length()
		if diff > 0.5:
			print("FAILED at ", tc.pos, ": got ", result, ", expected ", tc.expected, " (diff: ", diff, ")")
			all_passed = false
		else:
			print("PASSED at ", tc.pos, ": got ", result)

	if all_passed:
		print("ALL FIELD CONTROLLER TESTS PASSED!")
	else:
		print("SOME TESTS FAILED!")
	quit()

extends SceneTree

func _init():
	var scene = load("res://scenes/GravityLab.tscn")
	var root_node = scene.instantiate()
	var probe = root_node.get_node("Probe")
	print("Probe linear_damp: ", probe.linear_damp)
	print("Probe linear_damp_mode: ", probe.linear_damp_mode)

	for child in root_node.get_children():
		if child is Area2D:
			print(child.name, ": linear_damp=", child.linear_damp, " override=", child.linear_damp_space_override)
	quit()

extends RigidBody2D

var tick_count = 0

func _ready():
	global_position = Vector2(0, 0)
	linear_velocity = Vector2(0, 0)
	angular_velocity = 0.0

func _integrate_forces(state):
	tick_count += 1
	if tick_count == 1:
		var controller = get_parent()
		if controller and controller.has_method("net_gravity_at"):
			var correct_gravity = controller.net_gravity_at(state.transform.origin)
			var dt = state.step
			# Remove the default gravity applied on the first tick and apply the correct gravity
			var default_gravity = Vector2(0, 100)
			state.linear_velocity -= default_gravity * dt
			state.linear_velocity += correct_gravity * dt

